import { defineTool as defineTool3, ToolError as ToolError3 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z3 } from "npm:zod@^4.4.3";
var get_weather_default = defineTool3({
  name: "get_weather_forecast",
  title: "Get weather forecast",
  description: "Current conditions plus a multi-day forecast (high/low, precipitation chance) for a latitude/longitude.",
  inputSchema: {
    lat: z3.number().describe("Latitude."),
    lng: z3.number().describe("Longitude."),
    days: z3.number().optional().describe("Forecast days, 1-7. Defaults to 7.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },
  handler: async ({ lat, lng, days }) => {
    const span = Math.min(Math.max(Math.round(days ?? 7), 1), 7);
    const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}&current=temperature_2m,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,weather_code&forecast_days=${span}&timezone=auto&temperature_unit=fahrenheit`;
    const res = await fetch(url);
    if (!res.ok) throw new ToolError3(`Weather lookup failed (${res.status})`);
    const j = await res.json();
    const daily = (j.daily?.time ?? []).map((date, i) => ({
      date,
      highF: j.daily.temperature_2m_max?.[i] ?? null,
      lowF: j.daily.temperature_2m_min?.[i] ?? null,
      precipChance: j.daily.precipitation_probability_max?.[i] ?? null
    }));
    const current = {
      temperatureF: j.current?.temperature_2m ?? null,
      windMph: j.current?.wind_speed_10m ?? null
    };
    const text = [
      `Now: ${current.temperatureF ?? "?"}\xB0F, wind ${current.windMph ?? "?"} mph`,
      ...daily.map(
        (d) => `${d.date}: ${d.lowF ?? "?"}\u2013${d.highF ?? "?"}\xB0F, precip ${d.precipChance ?? 0}%`
      )
    ].join("\n");
    return { content: [{ type: "text", text }], structuredContent: { current, daily } };
  }
});

